#!/usr/bin/env bun
/**
 * CLI entry point for YAML file validation.
 *
 * Usage: bun run yaml-validator.ts [files...]
 *        bun run yaml-validator.ts --help
 */

import { validateYamlFile } from "./yaml-validation";

/**
 * Displays help message with usage instructions.
 */
function displayHelp(): void {
  console.log(`
YAML Validator

Usage:
  bun run yaml-validator.ts [files...]
  bun run yaml-validator.ts --help

Description:
  Validates YAML file syntax using Bun's built-in parser.
  Checks one or more files and reports any syntax errors.

Arguments:
  files...    One or more YAML file paths to validate

Options:
  --help      Display this help message

Exit Codes:
  0           All files are valid YAML
  1           One or more files have errors (invalid syntax, missing file, etc.)

Examples:
  bun run yaml-validator.ts config.yaml
  bun run yaml-validator.ts file1.yaml file2.yaml file3.yaml
`);
}

/**
 * Main CLI function that processes arguments and validates files.
 */
async function main(): Promise<void> {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    console.error("Error: No files specified");
    console.error("Run with --help for usage information");
    process.exit(1);
  }

  if (args.includes("--help") || args.includes("-h")) {
    displayHelp();
    process.exit(0);
  }

  const filePaths = args;
  let hasErrors = false;

  for (const filePath of filePaths) {
    const result = await validateYamlFile(filePath);

    if (result.valid) {
      console.log(`✓ ${result.filePath}: Valid YAML`);
    } else {
      hasErrors = true;
      console.error(`✗ ${result.filePath}: ${result.error}`, { stream: "stderr" });
    }
  }

  if (hasErrors) {
    process.exit(1);
  } else {
    process.exit(0);
  }
}

main().catch((error) => {
  console.error("Unexpected error:", error instanceof Error ? error.message : error);
  process.exit(1);
});

import { describe, expect, test, beforeAll, afterAll } from "bun:test";
import { validateYamlFile } from "./yaml-validation";
import { mkdirSync, writeFileSync, rmSync } from "fs";
import { join } from "path";
import { tmpdir } from "os";

const TEST_DIR = join(tmpdir(), "yaml-validation-test");

beforeAll(() => {
  mkdirSync(TEST_DIR, { recursive: true });
});

afterAll(() => {
  rmSync(TEST_DIR, { recursive: true, force: true });
});

describe("validateYamlFile", () => {
  describe("valid YAML", () => {
    test("validates simple object", async () => {
      const filePath = join(TEST_DIR, "valid-object.yaml");
      writeFileSync(filePath, "name: Alice\nage: 30\n");

      const result = await validateYamlFile(filePath);

      expect(result.valid).toBe(true);
      expect(result.filePath).toBe(filePath);
      expect(result.error).toBeUndefined();
    });

    test("validates array", async () => {
      const filePath = join(TEST_DIR, "valid-array.yaml");
      writeFileSync(filePath, "- item1\n- item2\n- item3\n");

      const result = await validateYamlFile(filePath);

      expect(result.valid).toBe(true);
      expect(result.filePath).toBe(filePath);
      expect(result.error).toBeUndefined();
    });

    test("validates scalar value", async () => {
      const filePath = join(TEST_DIR, "valid-scalar.yaml");
      writeFileSync(filePath, "simple string value\n");

      const result = await validateYamlFile(filePath);

      expect(result.valid).toBe(true);
      expect(result.filePath).toBe(filePath);
      expect(result.error).toBeUndefined();
    });

    test("validates multiline string", async () => {
      const filePath = join(TEST_DIR, "valid-multiline.yaml");
      writeFileSync(filePath, "description: |\n  This is a multiline\n  string value\n  with multiple lines\n");

      const result = await validateYamlFile(filePath);

      expect(result.valid).toBe(true);
      expect(result.filePath).toBe(filePath);
      expect(result.error).toBeUndefined();
    });

    test("validates nested structure", async () => {
      const filePath = join(TEST_DIR, "valid-nested.yaml");
      writeFileSync(filePath, "person:\n  name: Bob\n  address:\n    city: NYC\n    zip: 10001\n");

      const result = await validateYamlFile(filePath);

      expect(result.valid).toBe(true);
      expect(result.filePath).toBe(filePath);
      expect(result.error).toBeUndefined();
    });
  });

  describe("invalid YAML", () => {
    test("detects missing colon", async () => {
      const filePath = join(TEST_DIR, "invalid-missing-colon.yaml");
      writeFileSync(filePath, "name Alice\nage: 30\n");

      const result = await validateYamlFile(filePath);

      expect(result.valid).toBe(false);
      expect(result.filePath).toBe(filePath);
      expect(result.error).toContain(filePath);
      expect(result.error).toContain("YAML parse error");
    });

    test("detects bad indentation", async () => {
      const filePath = join(TEST_DIR, "invalid-indentation.yaml");
