    49→    console.error("Error: No files specified");
    50→    console.error("Run with --help for usage information");
    51→    process.exit(1);
    52→  }
    53→
    54→  if (args.includes("--help") || args.includes("-h")) {
    55→    displayHelp();
    56→    process.exit(0);
    57→  }
    58→
    59→  const filePaths = args;
    60→  let hasErrors = false;
    61→
    62→  for (const filePath of filePaths) {
    63→    const result = await validateYamlFile(filePath);
    64→
    65→    if (result.valid) {
    66→      console.log(`✓ ${result.filePath}: Valid YAML`);
    67→    } else {
    68→      hasErrors = true;
    69→      console.error(`✗ ${result.filePath}: ${result.error}`);
    70→    }
    71→  }
    72→
    73→  if (hasErrors) {
    74→    process.exit(1);
    75→  } else {
    76→    process.exit(0);
    77→  }
    78→}
