/**
 * YAML validation utilities using Bun's built-in YAML parser.
 */

/**
 * Result of validating a YAML file.
 */
export interface ValidationResult {
  valid: boolean;
  filePath: string;
  error?: string;
}

/**
 * Validates a YAML file by attempting to parse it.
 *
 * @param filePath - Path to the YAML file to validate
 * @returns Validation result indicating success or failure with error details
 */
export async function validateYamlFile(filePath: string): Promise<ValidationResult> {
  try {
    const file = Bun.file(filePath);

    const exists = await file.exists();
    if (!exists) {
      return {
        valid: false,
        filePath,
        error: `File not found: ${filePath}`
      };
    }

    const content = await file.text();

    if (content.trim() === '') {
      return {
        valid: true,
        filePath
      };
    }

    try {
      await Bun.YAML.parse(content);
      return {
        valid: true,
        filePath
      };
    } catch (parseError) {
      const errorMessage = parseError instanceof Error
        ? parseError.message
        : 'Unknown YAML parse error';

      return {
        valid: false,
        filePath,
        error: `YAML parse error in ${filePath}: ${errorMessage}`
      };
    }
  } catch (error) {
    const errorMessage = error instanceof Error
      ? error.message
      : 'Unknown error';

    if (errorMessage.includes('EACCES') || errorMessage.includes('permission denied')) {
      return {
        valid: false,
        filePath,
        error: `Permission denied: ${filePath}`
      };
    }

    return {
      valid: false,
      filePath,
      error: `Error reading ${filePath}: ${errorMessage}`
    };
  }
}

