     1→/**
     2→ * YAML validation utilities using Bun's built-in YAML parser.
     3→ */
     4→
     5→/**
     6→ * Result of validating a YAML file.
     7→ */
     8→export interface ValidationResult {
     9→  valid: boolean;
    10→  filePath: string;
    11→  error?: string;
    12→}
    13→
    14→/**
    15→ * Validates a YAML file by attempting to parse it.
    16→ *
    17→ * @param filePath - Path to the YAML file to validate
    18→ * @returns Validation result indicating success or failure with error details
    19→ */
    20→export async function validateYamlFile(filePath: string): Promise<ValidationResult> {
    21→  try {
    22→    const file = Bun.file(filePath);
    23→
    24→    const exists = await file.exists();
    25→    if (!exists) {
    26→      return {
    27→        valid: false,
    28→        filePath,
    29→        error: `File not found: ${filePath}`
    30→      };
    31→    }
    32→
    33→    const content = await file.text();
    34→
    35→    if (content.trim() === '') {
    36→      return {
    37→        valid: true,
    38→        filePath
    39→      };
    40→    }
    41→
    42→    try {
    43→      await Bun.YAML.parse(content);
    44→      return {
    45→        valid: true,
    46→        filePath
    47→      };
    48→    } catch (parseError) {
    49→      const errorMessage = parseError instanceof Error
    50→        ? parseError.message
    51→        : 'Unknown YAML parse error';
    52→
    53→      return {
    54→        valid: false,
    55→        filePath,
    56→        error: `YAML parse error in ${filePath}: ${errorMessage}`
    57→      };
    58→    }
    59→  } catch (error) {
    60→    const errorMessage = error instanceof Error
    61→      ? error.message
    62→      : 'Unknown error';
    63→
    64→    if (errorMessage.includes('EACCES') || errorMessage.includes('permission denied')) {
    65→      return {
    66→        valid: false,
    67→        filePath,
    68→        error: `Permission denied: ${filePath}`
    69→      };
    70→    }
    71→
    72→    return {
    73→      valid: false,
    74→      filePath,
    75→      error: `Error reading ${filePath}: ${errorMessage}`
    76→    };
    77→  }
    78→}
    79→

