import { beforeAll, afterAll, describe, expect, test } from "bun:test";
import { join } from "path";
import { mkdtemp, rm, writeFile } from "fs/promises";
import { tmpdir } from "os";

describe("yaml-validator CLI", () => {
  let testDir: string;
  let validFile: string;
  let invalidFile: string;
  let anotherValidFile: string;

  beforeAll(async () => {
    testDir = await mkdtemp(join(tmpdir(), "yaml-validator-cli-test-"));

    validFile = join(testDir, "valid.yaml");
    await writeFile(
      validFile,
      `name: test
version: 1.0.0
items:
  - one
  - two
`
    );

    invalidFile = join(testDir, "invalid.yaml");
    await writeFile(
      invalidFile,
      `name test
invalid: [unclosed array
`
    );

    anotherValidFile = join(testDir, "another-valid.yaml");
    await writeFile(
      anotherValidFile,
      `simple: value
nested:
  key: value
`
    );
  });

  afterAll(async () => {
    await rm(testDir, { recursive: true, force: true });
  });

  test("CLI with single valid file exits with code 0", async () => {
    const proc = Bun.spawn(["bun", "run", "src/yaml-validator.ts", validFile]);
    const exitCode = await proc.exited;

    expect(exitCode).toBe(0);
  });

  test("CLI with single valid file outputs success to stdout", async () => {
    const proc = Bun.spawn(["bun", "run", "src/yaml-validator.ts", validFile], {
      stdout: "pipe",
    });

    const stdout = await new Response(proc.stdout).text();
    const exitCode = await proc.exited;

    expect(exitCode).toBe(0);
    expect(stdout).toContain("✓");
    expect(stdout).toContain(validFile);
    expect(stdout).toContain("Valid YAML");
  });

  test("CLI with single invalid file exits with code 1", async () => {
    const proc = Bun.spawn(["bun", "run", "src/yaml-validator.ts", invalidFile]);
    const exitCode = await proc.exited;

    expect(exitCode).toBe(1);
  });

  test("CLI with single invalid file outputs error to stderr with file path", async () => {
    const proc = Bun.spawn(["bun", "run", "src/yaml-validator.ts", invalidFile], {
      stderr: "pipe",
    });

    const stderr = await new Response(proc.stderr).text();
    const exitCode = await proc.exited;

    expect(exitCode).toBe(1);
    expect(stderr).toContain("✗");
    expect(stderr).toContain(invalidFile);
  });

  test("CLI with multiple valid files exits with code 0", async () => {
    const proc = Bun.spawn([
      "bun",
      "run",
      "src/yaml-validator.ts",
      validFile,
      anotherValidFile,
    ]);
    const exitCode = await proc.exited;

    expect(exitCode).toBe(0);
  });

  test("CLI with multiple files (mix of valid/invalid) exits with code 1", async () => {
    const proc = Bun.spawn([
      "bun",
      "run",
      "src/yaml-validator.ts",
      validFile,
      invalidFile,
      anotherValidFile,
    ]);
    const exitCode = await proc.exited;

    expect(exitCode).toBe(1);
  });

  test("CLI with multiple files reports all results", async () => {
    const proc = Bun.spawn(
      [
        "bun",
        "run",
        "src/yaml-validator.ts",
        validFile,
        invalidFile,
        anotherValidFile,
      ],
      {
        stdout: "pipe",
        stderr: "pipe",
      }
    );

    const stdout = await new Response(proc.stdout).text();
    const stderr = await new Response(proc.stderr).text();
    const exitCode = await proc.exited;

    expect(exitCode).toBe(1);
    expect(stdout).toContain(validFile);
    expect(stdout).toContain(anotherValidFile);
    expect(stderr).toContain(invalidFile);
  });

  test("CLI with non-existent file exits with code 1", async () => {
    const nonExistentFile = join(testDir, "does-not-exist.yaml");
    const proc = Bun.spawn(["bun", "run", "src/yaml-validator.ts", nonExistentFile]);
    const exitCode = await proc.exited;

    expect(exitCode).toBe(1);
  });

  test("CLI with non-existent file outputs error to stderr with file path", async () => {
    const nonExistentFile = join(testDir, "does-not-exist.yaml");
    const proc = Bun.spawn(["bun", "run", "src/yaml-validator.ts", nonExistentFile], {
      stderr: "pipe",
    });

    const stderr = await new Response(proc.stderr).text();
    const exitCode = await proc.exited;

    expect(exitCode).toBe(1);
    expect(stderr).toContain(nonExistentFile);
    expect(stderr).toContain("File not found");
  });

  test("CLI with --help flag exits with code 0", async () => {
    const proc = Bun.spawn(["bun", "run", "src/yaml-validator.ts", "--help"]);
    const exitCode = await proc.exited;

    expect(exitCode).toBe(0);
  });

  test("CLI with --help flag displays usage information", async () => {
    const proc = Bun.spawn(["bun", "run", "src/yaml-validator.ts", "--help"], {
      stdout: "pipe",
    });

    const stdout = await new Response(proc.stdout).text();
    const exitCode = await proc.exited;

    expect(exitCode).toBe(0);
    expect(stdout).toContain("YAML Validator");
    expect(stdout).toContain("Usage:");
    expect(stdout).toContain("bun run yaml-validator.ts");
    expect(stdout).toContain("Exit Codes:");
  });

  test("CLI with -h flag displays usage information", async () => {
    const proc = Bun.spawn(["bun", "run", "src/yaml-validator.ts", "-h"], {
      stdout: "pipe",
    });

    const stdout = await new Response(proc.stdout).text();
    const exitCode = await proc.exited;

    expect(exitCode).toBe(0);
    expect(stdout).toContain("YAML Validator");
  });

  test("CLI with no arguments exits with code 1", async () => {
    const proc = Bun.spawn(["bun", "run", "src/yaml-validator.ts"]);
    const exitCode = await proc.exited;

    expect(exitCode).toBe(1);
  });

  test("CLI with no arguments displays error message", async () => {
    const proc = Bun.spawn(["bun", "run", "src/yaml-validator.ts"], {
      stderr: "pipe",
    });

    const stderr = await new Response(proc.stderr).text();
    const exitCode = await proc.exited;

    expect(exitCode).toBe(1);
    expect(stderr).toContain("No files specified");
    expect(stderr).toContain("--help");
  });
});

